SELECT COUNT(DISTINCT "Eixo_1"."Calculation_838513981462429699") AS "ctd_Calculation_838513981462429699_ok",   CAST(EXTRACT(YEAR FROM "Eixo_1"."data_de_inicio") AS BIGINT) AS "yr_data_de_inicio_ok" FROM "Eixo_1" WHERE ((NOT (("Eixo_1"."nome_da_sit_matricula__situacao_detalhada_" IN ('CANC_DESISTENTE', 'CANC_MAT_PRIM_OPCAO', 'CANC_SANÇÃO', 'CANC_SEM_FREQ_INICIAL', 'CANC_TURMA', 'DOC_INSUFIC', 'ESCOL_INSUFIC', 'INC _ITINERARIO', 'INSC_CANC', 'Não Matriculado', 'NÃO_COMPARECEU', 'TURMA_CANC', 'VAGAS_INSUFIC')) OR ("Eixo_1"."nome_da_sit_matricula__situacao_detalhada_" IS NULL))) AND (NOT ("Eixo_1"."situacao_da_turma" IN ('CANCELADA', 'CRIADA', 'PUBLICADA'))) AND ("Eixo_1"."uf_do_local_da_oferta" = 'PE')) GROUP BY "yr_data_de_inicio_ok";
